        tree.SetDimension(root, Dimension.Width, StyleLength.Points(52.0f));
        tree.SetJustifyContent(root, Justify.Center);

        var rootChild0 = tree.CreateNode();
        tree.SetDimension(rootChild0, Dimension.Width, StyleLength.Points(72.0f));
        tree.SetDimension(rootChild0, Dimension.Height, StyleLength.Points(72.0f));
        tree.SetMargin(rootChild0, Edge.Left, StyleLength.Auto);
        tree.SetMargin(rootChild0, Edge.Right, StyleLength.Auto);
        tree.InsertChild(root, rootChild0, 0);
        tree.CalculateLayout(root, float.NaN, float.NaN, Direction.Ltr);

        Assert.Equal(0.0f, tree.GetLeft(root), Tolerance);
        Assert.Equal(0.0f, tree.GetTop(root), Tolerance);
        Assert.Equal(52.0f, tree.GetWidth(root), Tolerance);
        Assert.Equal(52.0f, tree.GetHeight(root), Tolerance);

        Assert.Equal(0.0f, tree.GetLeft(rootChild0), Tolerance);
        Assert.Equal(-10.0f, tree.GetTop(rootChild0), Tolerance);
        Assert.Equal(72.0f, tree.GetWidth(rootChild0), Tolerance);
        Assert.Equal(72.0f, tree.GetHeight(rootChild0), Tolerance);

        tree.CalculateLayout(root, float.NaN, float.NaN, Direction.Rtl);

        Assert.Equal(0.0f, tree.GetLeft(root), Tolerance);
        Assert.Equal(0.0f, tree.GetTop(root), Tolerance);
        Assert.Equal(52.0f, tree.GetWidth(root), Tolerance);
        Assert.Equal(52.0f, tree.GetHeight(root), Tolerance);

        Assert.Equal(-20.0f, tree.GetLeft(rootChild0), Tolerance);
        Assert.Equal(-10.0f, tree.GetTop(rootChild0), Tolerance);
        Assert.Equal(72.0f, tree.GetWidth(rootChild0), Tolerance);
        Assert.Equal(72.0f, tree.GetHeight(rootChild0), Tolerance);
    }

